/**
 * Portable flow format — import / export.
 *
 * A flow is exported as one self-contained JSON document so it can be
 * moved between accounts or self-hosted instances, version-controlled,
 * or generated by another tool and pushed in over the API.
 *
 * Differences from the raw DB rows (so the file stays portable):
 *   - No UUIDs. Nodes are addressed by their stable `node_key`.
 *   - `set_tag` nodes reference a tag by `tag_name` instead of a
 *     `tag_id`, because tag UUIDs are per-account. On import the tag is
 *     looked up by name (and created when missing).
 *   - Node positions are optional. When every node is at (0,0) the
 *     canvas auto-lays-out the graph on first open.
 *
 * This module is pure (no I/O) so it can be unit-tested and reused by
 * both the dashboard route and the public API.
 */

import type { FlowFallbackPolicy } from "./types";
import { DEFAULT_FALLBACK_POLICY } from "./types";

export const FLOW_EXPORT_VERSION = 1;

export const IMPORTABLE_NODE_TYPES = [
  "start",
  "send_message",
  "send_buttons",
  "send_list",
  "send_media",
  "collect_input",
  "condition",
  "set_tag",
  "handoff",
  "end",
] as const;
export type ImportableNodeType = (typeof IMPORTABLE_NODE_TYPES)[number];

export const TRIGGER_TYPES = [
  "keyword",
  "first_inbound_message",
  "manual",
] as const;
export type ImportTriggerType = (typeof TRIGGER_TYPES)[number];

export const MAX_IMPORT_NODES = 300;
const NODE_KEY_RE = /^[A-Za-z0-9_.-]{1,64}$/;

export interface PortableNode {
  node_key: string;
  node_type: ImportableNodeType;
  config: Record<string, unknown>;
  position_x: number;
  position_y: number;
}

export interface PortableFlow {
  wacrm_flow_version: number;
  name: string;
  description: string | null;
  trigger_type: ImportTriggerType;
  trigger_config: Record<string, unknown>;
  fallback_policy: FlowFallbackPolicy;
  entry_node_id: string | null;
  nodes: PortableNode[];
}

export type ParseResult =
  | { ok: true; value: PortableFlow }
  | { ok: false; errors: string[] };

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/**
 * Validate the *shape* of an import document and normalise it. This is
 * deliberately separate from `validateFlowForActivation`: a draft may
 * be incomplete (the user finishes it in the builder), but a document
 * that isn't structurally a flow can't be stored at all.
 *
 * Accepts both the wrapped form `{ flow: {...} }` and the bare form.
 * `entry_node_key` is accepted as an alias of `entry_node_id`.
 */
export function parseFlowImport(input: unknown): ParseResult {
  const errors: string[] = [];
  const root = isRecord(input) && isRecord(input.flow) ? input.flow : input;
  if (!isRecord(root)) {
    return { ok: false, errors: ["Body must be a JSON object."] };
  }

  const name = typeof root.name === "string" ? root.name.trim() : "";
  if (!name) errors.push("`name` is required.");
  if (name.length > 120) errors.push("`name` must be 120 characters or fewer.");

  const trigger_type = (root.trigger_type ?? "keyword") as string;
  if (!(TRIGGER_TYPES as readonly string[]).includes(trigger_type)) {
    errors.push(
      "`trigger_type` must be one of keyword, first_inbound_message, manual.",
    );
  }

  const trigger_config = isRecord(root.trigger_config) ? root.trigger_config : {};
  if (root.trigger_config !== undefined && !isRecord(root.trigger_config)) {
    errors.push("`trigger_config` must be an object.");
  }

  let fallback: FlowFallbackPolicy = { ...DEFAULT_FALLBACK_POLICY };
  if (root.fallback_policy !== undefined) {
    if (!isRecord(root.fallback_policy)) {
      errors.push("`fallback_policy` must be an object.");
    } else {
      const f = root.fallback_policy;
      if (
        f.on_unknown_reply !== undefined &&
        !["reprompt", "handoff", "ignore"].includes(f.on_unknown_reply as string)
      ) {
        errors.push("`fallback_policy.on_unknown_reply` is invalid.");
      }
      if (
        f.on_exhaust !== undefined &&
        !["handoff", "end"].includes(f.on_exhaust as string)
      ) {
        errors.push("`fallback_policy.on_exhaust` is invalid.");
      }
      fallback = { ...fallback, ...(f as Partial<FlowFallbackPolicy>) };
    }
  }

  if (!Array.isArray(root.nodes) || root.nodes.length === 0) {
    errors.push("`nodes` must be a non-empty array.");
    return { ok: false, errors };
  }
  if (root.nodes.length > MAX_IMPORT_NODES) {
    errors.push(`A flow can have at most ${MAX_IMPORT_NODES} nodes.`);
    return { ok: false, errors };
  }

  const nodes: PortableNode[] = [];
  const seen = new Set<string>();
  root.nodes.forEach((raw: unknown, i: number) => {
    if (!isRecord(raw)) {
      errors.push(`nodes[${i}] must be an object.`);
      return;
    }
    const key = typeof raw.node_key === "string" ? raw.node_key : "";
    if (!NODE_KEY_RE.test(key)) {
      errors.push(
        `nodes[${i}].node_key must be 1-64 chars of letters, digits, _ . -`,
      );
      return;
    }
    if (seen.has(key)) {
      errors.push(`Duplicate node_key "${key}".`);
      return;
    }
    seen.add(key);
    if (
      typeof raw.node_type !== "string" ||
      !(IMPORTABLE_NODE_TYPES as readonly string[]).includes(raw.node_type)
    ) {
      errors.push(
        `nodes[${i}] ("${key}") has unknown node_type "${String(raw.node_type)}".`,
      );
      return;
    }
    if (!isRecord(raw.config ?? {})) {
      errors.push(`nodes[${i}] ("${key}").config must be an object.`);
      return;
    }
    nodes.push({
      node_key: key,
      node_type: raw.node_type as ImportableNodeType,
      config: (raw.config as Record<string, unknown>) ?? {},
      position_x: Number.isFinite(raw.position_x) ? Math.round(raw.position_x as number) : 0,
      position_y: Number.isFinite(raw.position_y) ? Math.round(raw.position_y as number) : 0,
    });
  });

  if (errors.length > 0) return { ok: false, errors };

  // Entry node: explicit alias → "start" node if present → first start node.
  let entry: string | null =
    typeof root.entry_node_id === "string"
      ? root.entry_node_id
      : typeof root.entry_node_key === "string"
        ? root.entry_node_key
        : null;
  if (!entry) {
    entry = nodes.find((n) => n.node_key === "start")?.node_key
      ?? nodes.find((n) => n.node_type === "start")?.node_key
      ?? null;
  }

  return {
    ok: true,
    value: {
      wacrm_flow_version: FLOW_EXPORT_VERSION,
      name,
      description:
        typeof root.description === "string" && root.description.trim()
          ? root.description.trim()
          : null,
      trigger_type: trigger_type as ImportTriggerType,
      trigger_config,
      fallback_policy: fallback,
      entry_node_id: entry,
      nodes,
    },
  };
}

/** Tag names referenced by `set_tag` nodes via `tag_name` (de-duplicated). */
export function collectTagNames(nodes: PortableNode[]): string[] {
  const out = new Set<string>();
  for (const n of nodes) {
    if (n.node_type === "set_tag" && typeof n.config.tag_name === "string") {
      const t = n.config.tag_name.trim();
      if (t) out.add(t);
    }
  }
  return [...out];
}

/**
 * Swap `tag_name` for `tag_id` on set_tag nodes using a name→id map.
 * Nodes that already carry a `tag_id` and no `tag_name` are untouched.
 */
export function applyTagIds(
  nodes: PortableNode[],
  tagIdByName: Map<string, string>,
): PortableNode[] {
  return nodes.map((n) => {
    if (n.node_type !== "set_tag") return n;
    const { tag_name, ...rest } = n.config as Record<string, unknown> & {
      tag_name?: string;
    };
    if (typeof tag_name !== "string") return n;
    const id = tagIdByName.get(tag_name.trim());
    return { ...n, config: { ...rest, ...(id ? { tag_id: id } : {}) } };
  });
}

/**
 * Build the export document from DB rows. `tagNameById` converts each
 * set_tag node's account-local `tag_id` back into a portable name.
 */
export function buildFlowExport(
  flow: {
    name: string;
    description: string | null;
    trigger_type: string;
    trigger_config: Record<string, unknown>;
    fallback_policy: Record<string, unknown>;
    entry_node_id: string | null;
  },
  nodes: Array<{
    node_key: string;
    node_type: string;
    config: Record<string, unknown>;
    position_x?: number;
    position_y?: number;
  }>,
  tagNameById: Map<string, string>,
) {
  return {
    wacrm_flow_version: FLOW_EXPORT_VERSION,
    name: flow.name,
    description: flow.description,
    trigger_type: flow.trigger_type,
    trigger_config: flow.trigger_config,
    fallback_policy: flow.fallback_policy,
    entry_node_id: flow.entry_node_id,
    nodes: nodes.map((n) => {
      let config = n.config;
      if (n.node_type === "set_tag" && typeof config.tag_id === "string") {
        const { tag_id, ...rest } = config as Record<string, unknown> & {
          tag_id: string;
        };
        const tagName = tagNameById.get(tag_id);
        config = tagName ? { ...rest, tag_name: tagName } : { ...rest, tag_id };
      }
      return {
        node_key: n.node_key,
        node_type: n.node_type,
        config,
        position_x: n.position_x ?? 0,
        position_y: n.position_y ?? 0,
      };
    }),
  };
}
